users = list_users()
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

-- Get availability for every user on every date (all run in parallel)
avails = for user in users {
    per_date = for date in dates {
        avail = get_availability({ user_id: user.id, date: date })
        return { user_id: user.id, date: date, busy: avail.busy if avail.busy != null else [] }
    }
    return per_date
}

-- Flatten: list of { user_id, date, busy[] }
flat = fold acc = [] for user_avails in avails {
    return acc + user_avails
}

-- Now analyze each day. For each date, we need to check all 30-min boundary slots from 09:00 to 16:00
-- Working hours: 09:00-17:00. 60-min slots starting on :00 or :30: 09:00-10:00, 09:30-10:30, ..., 16:00-17:00.

-- For each date, gather all users' busy intervals
-- Then check each candidate slot.

-- For a given date and candidate slot [start, end], check if any user has a busy interval overlapping it.
-- Overlap: busy_start < slot_end AND busy_end > slot_start

candidate_starts = ["09:00", "09:30", "10:00", "10:30", "11:00", "11:30", "12:00", "12:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00"]

result = null

by_date = fold acc = {} for entry in flat {
    list_for_date = acc[entry.date] if entry.date in acc else []
    return acc + { [entry.date]: list_for_date + [entry] }
}

result_date = null
result_start = null

for date in dates {
    entries = by_date[date] if date in by_date else []
    if entries == [] { continue }

    for start_str in candidate_starts {
        start_min = number.parse(text.split(start_str, ":")[0]) * 60 + number.parse(text.split(start_str, ":")[1])
        end_min = start_min + 60

        -- Check all users are free
        all_free = true
        for entry in entries {
            for busy in entry.busy {
                busy_start_str = busy.start if busy.start != null else "00:00"
                busy_end_str = busy.end if busy.end != null else "24:00"
                busy_start = number.parse(text.split(busy_start_str, ":")[0]) * 60 + number.parse(text.split(busy_start_str, ":")[1])
                busy_end = number.parse(text.split(busy_end_str, ":")[0]) * 60 + number.parse(text.split(busy_end_str, ":")[1])
                if busy_start < end_min and busy_end > start_min {
                    all_free = false
                }
            }
        }

        if all_free and result == null {
            result = { date: date, start: start_str }
        }
    }
}

return { result, by_date, flat }

